// NODO CODE: NORMALIZACIÓN MULTI-CAPA FUZZY, ROLLUP Y DIFFING CERO REIMPRESIÓN (SANDBOX PURA)

// 1. Obtener datos de Supabase (ya ejecutado en paso 1) y Google Sheets ($input.all())
const dbData = $('1. Consultar Choferes y Estado Preexistente (Supabase)').first().json;
const choferes = dbData.choferes || [];
const preexistentes = dbData.preexistentes || [];
const rawRows = $input.all().map(i => i.json);

// 2. Arquitectura de Normalización Multi-Capa y Fuzzy Resolver
function restoreEnie(str) {
  if (!str) return { restored: '', hadHashOrMojibake: false };
  const orig = String(str).trim();
  const hadHashOrMojibake = /#|Ã‘|Ã±|\uFFFD/.test(orig);
  const restored = orig
    .replace(/Ã‘|Ã±|\uFFFD/g, 'Ñ')
    .replace(/#/g, 'Ñ')
    .replace(/\s+/g, ' ')
    .trim();
  return { restored, hadHashOrMojibake };
}

function sanitizeNameAscii(str) {
  if (!str) return '';
  return restoreEnie(str).restored
    .replace(/[ñÑ]/g, 'N')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toUpperCase()
    .replace(/[^A-Z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function getSignificantTokens(str) {
  const stopWords = new Set(['DE', 'DEL', 'LA', 'LAS', 'LOS', 'Y', 'SAN', 'SANTA']);
  return sanitizeNameAscii(str).split(' ').filter(t => t && !stopWords.has(t));
}

function sortedTokenKey(str) {
  return getSignificantTokens(str).slice().sort().join(' ');
}

function levenshtein(a, b) {
  if (a === b) return 0;
  const m = a.length, n = b.length;
  if (m === 0) return n;
  if (n === 0) return m;
  let prev = new Array(n + 1);
  let curr = new Array(n + 1);
  for (let j = 0; j <= n; j++) prev[j] = j;
  for (let i = 1; i <= m; i++) {
    curr[0] = i;
    const ca = a.charCodeAt(i - 1);
    for (let j = 1; j <= n; j++) {
      const cost = ca === b.charCodeAt(j - 1) ? 0 : 1;
      curr[j] = Math.min(prev[j] + 1, curr[j - 1] + 1, prev[j - 1] + cost);
    }
    const tmp = prev; prev = curr; curr = tmp;
  }
  return prev[n];
}

function tokenSimilarity(t1, t2) {
  if (t1 === t2) return 1.0;
  const maxLen = Math.max(t1.length, t2.length);
  return maxLen === 0 ? 1.0 : 1.0 - levenshtein(t1, t2) / maxLen;
}

const KNOWN_ALIASES = {
  'ACUNA SANTIAGO': 'ACUÑA RAFAEL SANTIAGO',
  'AGUERO ALEXIS': 'AGUERO ALEXIS DAMIAN',
  'ALANIZ CRISTIAN PAULO': 'ALANIZ CRISTIAN PAULO',
  'MENDOZA ERWIN GONZALO': 'MENDOZA REYES ERWIN GONZALO',
  'POO NARVAEZ JAIRO': 'POO NARVAEZ JAIRO BERNABE',
  'SANDOVAL DARIO': 'SANDOVAL REYES CRISTIAN EDUARDO',
  'LEONARDO ARIEL GUEVARA': 'GUEVARA LEONARDO A',
  'GUEVARA LEONARDO ARIEL': 'GUEVARA LEONARDO A',
  'RAMOS GONZALO DAVID': 'RAMOS DAVID GONZALO',
  'RAMOS DAVID GONZALO': 'RAMOS DAVID GONZALO'
};

// Indexar choferes catalogados con arquitectura multi-capa
const bySanitized = new Map();
const bySortedTokens = new Map();
const byTokensList = [];

for (const c of choferes) {
  if (!c || !c.nombre) continue;
  const san = sanitizeNameAscii(c.nombre);
  const sKey = sortedTokenKey(c.nombre);
  const tokens = getSignificantTokens(c.nombre);
  bySanitized.set(san, c);
  bySortedTokens.set(sKey, c);
  byTokensList.push({ chofer: c, tokens, tokenSet: new Set(tokens), mainSurname: tokens[0] });
}

function resolveChoferParticion1(rawName) {
  if (!rawName) return null;
  const { restored } = restoreEnie(rawName);
  const san = sanitizeNameAscii(restored);
  if (!san || san.length < 3 || san.startsWith('NO IDENTIFICADO') || san.startsWith('TOTAL') || san === 'CHOFER' || san.startsWith('PERSONAL')) return null;

  if (bySanitized.has(san)) return bySanitized.get(san);
  if (KNOWN_ALIASES[san]) {
    const aliasT = sanitizeNameAscii(KNOWN_ALIASES[san]);
    if (bySanitized.has(aliasT)) return bySanitized.get(aliasT);
  }
  const sKey = sortedTokenKey(restored);
  if (bySortedTokens.has(sKey)) return bySortedTokens.get(sKey);

  const kTokens = getSignificantTokens(restored);
  const kSet = new Set(kTokens);
  if (kTokens.length >= 2) {
    const cands = byTokensList.filter(it => {
      const surnameMatch = it.mainSurname === kTokens[0] || tokenSimilarity(it.mainSurname, kTokens[0]) >= 0.85;
      if (!surnameMatch) return false;
      const kInIt = kTokens.every(t => it.tokenSet.has(t) || Array.from(it.tokenSet).some(itT => tokenSimilarity(t, itT) >= 0.85));
      const itInK = it.tokens.every(t => kSet.has(t) || Array.from(kSet).some(kt => tokenSimilarity(t, kt) >= 0.85));
      return kInIt || itInK;
    });
    if (cands.length === 1) return cands[0].chofer;
  }

  let bestCand = null, bestSim = 0;
  for (const item of byTokensList) {
    const surnameSim = Math.max(...kTokens.map(kt => tokenSimilarity(item.mainSurname, kt)));
    if (surnameSim < 0.72) continue;
    const shorter = kTokens.length <= item.tokens.length ? kTokens : item.tokens;
    const longer = kTokens.length <= item.tokens.length ? item.tokens : kTokens;
    if (shorter.length === 0) continue;
    let sumSim = 0;
    for (const st of shorter) {
      let maxS = 0;
      for (let i = 0; i < longer.length; i++) {
        const s = tokenSimilarity(st, longer[i]);
        if (s > maxS) maxS = s;
      }
      sumSim += maxS;
    }
    const score = sumSim / shorter.length;
    if (score > bestSim) { bestSim = score; bestCand = item.chofer; }
  }
  if (bestSim >= 0.80 && bestCand) return bestCand;
  return null;
}

const resolveCache = new Map();
function resolveChoferCached(rawName) {
  if (!rawName) return null;
  if (resolveCache.has(rawName)) return resolveCache.get(rawName);
  const resolved = resolveChoferParticion1(rawName);
  resolveCache.set(rawName, resolved);
  return resolved;
}

// Indexar estado preexistente de Supabase por (chofer_id__mes_tab)
const preMap = new Map();
preexistentes.forEach(p => {
  if (p && p.chofer_id && p.mes_tab) {
    preMap.set(`${p.chofer_id}__${p.mes_tab}`, p);
  }
});

// 3. Funciones auxiliares de parseo
function parseFecha(val) {
  if (!val) return null;
  const clean = String(val).split(' - ')[0].trim();
  const parts = clean.split(/[\/\-]/);
  if (parts.length === 3) {
    let y = parseInt(parts[2], 10);
    if (y < 100) y += 2000;
    const m = String(parseInt(parts[1], 10)).padStart(2, '0');
    const d = String(parseInt(parts[0], 10)).padStart(2, '0');
    if (!isNaN(y) && !isNaN(parseInt(m, 10)) && !isNaN(parseInt(d, 10))) {
      return `${y}-${m}-${d}`;
    }
  }
  if (/^\d{4}-\d{2}-\d{2}/.test(clean)) return clean.substring(0, 10);
  return null;
}

function parseNum(val) {
  if (!val) return 0;
  const clean = String(val).replace(/,/g, '.').replace(/[^0-9.-]/g, '');
  const n = parseFloat(clean);
  return isNaN(n) ? 0 : n;
}

function getVal(row, colIndex, possibleNames) {
  for (const name of possibleNames) {
    if (row[name] !== undefined && row[name] !== '') return String(row[name]).trim();
  }
  const dataKeys = Object.keys(row).filter(k => k !== 'row_number');
  if (dataKeys[colIndex] !== undefined && row[dataKeys[colIndex]] !== undefined) {
    return String(row[dataKeys[colIndex]]).trim();
  }
  return '';
}

const MESES_ES = ['Ene', 'Feb', 'Mar', 'Abr', 'May', 'Jun', 'Jul', 'Ago', 'Sep', 'Oct', 'Nov', 'Dic'];
const buckets = new Map();
const inconsistencias = [];
let fuzzyMatchesCount = 0;

// 4. Procesar filas de la hoja KM
for (const row of rawRows) {
  const dominio = getVal(row, 0, ['Dominio', 'Tractor', 'dominio']).toUpperCase();
  const rawFecha = getVal(row, 1, ['Fecha', 'fecha']);
  const fechaIso = parseFecha(rawFecha);
  const choferRaw = getVal(row, 2, ['Chofer', 'CHOFER', 'chofer', 'Nombre']);

  const rawKmTot = getVal(row, 16, ['Km Totales', 'km_totales', 'Total KM']);
  const rawKmAlt = getVal(row, 10, ['Kilometros', 'kilometros', 'KM']);
  const km = parseNum(rawKmTot) || parseNum(rawKmAlt);
  const hr = getVal(row, 19, ['Nº Hoja de Ruta', 'Hoja de Ruta', 'hoja_ruta']);

  if (!fechaIso || (km <= 0 && !hr)) continue;

  const matchedChofer = resolveChoferCached(choferRaw);
  const choferId = matchedChofer ? matchedChofer.id : null;

  // Si no está en catálogo de choferes de Supabase -> Auditar como inconsistencia
  if (!choferId) {
    if (choferRaw && choferRaw !== '1' && choferRaw.length >= 3 && choferRaw.toUpperCase() !== 'SIN CHOFER ASIGNADO') {
      inconsistencias.push({
        fecha: fechaIso,
        chofer: choferRaw,
        dominio: dominio || 'S/D',
        km,
        hoja_ruta: hr || 'S/HR',
        motivo: 'CHOFER_NO_CATALOGADO',
        timestamp: new Date().toISOString()
      });
    }
    continue;
  }

  if (matchedChofer.nombre !== choferRaw.trim().toUpperCase()) {
    fuzzyMatchesCount++;
  }

  const dParts = fechaIso.split('-');
  const anio = parseInt(dParts[0], 10);
  const mesNum = parseInt(dParts[1], 10);
  const mesTab = `${MESES_ES[mesNum - 1]}-${String(anio).slice(-2)}`;
  const bucketKey = `${choferId}__${mesTab}`;

  if (!buckets.has(bucketKey)) {
    buckets.set(bucketKey, {
      chofer_id: choferId,
      chofer_nombre: matchedChofer.nombre,
      mes_tab: mesTab,
      anio,
      mes_numero: mesNum,
      km_mes_total: 0,
      cant_viajes: 0,
      dias_km: {},
      fechasList: []
    });
  }

  const b = buckets.get(bucketKey);
  b.km_mes_total += km;
  b.cant_viajes += 1;

  if (!b.dias_km[fechaIso]) {
    b.dias_km[fechaIso] = {
      km: 0,
      hr: hr || '',
      tractor: dominio || null
    };
    b.fechasList.push(fechaIso);
  }
  b.dias_km[fechaIso].km = Math.round((b.dias_km[fechaIso].km + km) * 100) / 100;
  if (hr && !b.dias_km[fechaIso].hr.includes(hr)) {
    b.dias_km[fechaIso].hr = b.dias_km[fechaIso].hr ? `${b.dias_km[fechaIso].hr}, ${hr}` : hr;
  }
}

// 5. Diffing O(1) en Memoria contra Supabase
let omitidosCount = 0;
let modificadosCount = 0;
const itemsParaUpsert = [];

const hoyStr = new Date().toISOString().split('T')[0];
const reportFilePath = `C:\\Users\\Matias Rodriguez\\Documents\\reportes\\km\\choferes_desvinculados_${hoyStr}.xlsx`;

for (const [key, b] of buckets.entries()) {
  b.km_mes_total = Math.round(b.km_mes_total * 100) / 100;

  // Construir rangos consecutivos
  const sortedFechas = b.fechasList.sort();
  const rangos = [];
  let curRango = null;

  sortedFechas.forEach(fStr => {
    const curDate = new Date(fStr + 'T12:00:00Z');
    if (!curRango) {
      curRango = { desde: fStr, hasta: fStr, dias: 1, km: b.dias_km[fStr].km };
    } else {
      const prevDate = new Date(curRango.hasta + 'T12:00:00Z');
      const diffDays = Math.round((curDate - prevDate) / (1000 * 3600 * 24));
      if (diffDays === 1) {
        curRango.hasta = fStr;
        curRango.dias += 1;
        curRango.km = Math.round((curRango.km + b.dias_km[fStr].km) * 100) / 100;
      } else {
        rangos.push(curRango);
        curRango = { desde: fStr, hasta: fStr, dias: 1, km: b.dias_km[fStr].km };
      }
    }
  });
  if (curRango) rangos.push(curRango);
  b.rangos = rangos;

  // DIFFING: Comparar contra el estado existente en Supabase
  const pre = preMap.get(key);
  if (pre) {
    const sameKm = Math.abs(pre.km_mes_total - b.km_mes_total) < 0.01;
    const sameTrips = pre.cant_viajes === b.cant_viajes;

    let sameDays = false;
    const preDays = pre.dias_km || {};
    const bDays = b.dias_km || {};
    const bDayKeys = Object.keys(bDays);
    const preDayKeys = Object.keys(preDays);

    if (bDayKeys.length === preDayKeys.length) {
      sameDays = bDayKeys.every(k => {
        const pd = preDays[k];
        const bd = bDays[k];
        return pd && Math.abs((pd.km || 0) - (bd.km || 0)) < 0.01 && (pd.hr || '') === (bd.hr || '');
      });
    }

    if (sameKm && sameTrips && sameDays) {
      omitidosCount++;
      continue; // CERO REIMPRESIÓN: No se emite a Postgres
    }
  }

  modificadosCount++;
  itemsParaUpsert.push({
    chofer_id: b.chofer_id,
    mes_tab: b.mes_tab,
    anio: b.anio,
    mes_numero: b.mes_numero,
    km_mes_total: b.km_mes_total,
    cant_viajes: b.cant_viajes,
    dias_km: b.dias_km,
    rangos: b.rangos
  });
}

// 6. Retornar payload Bulk Batch unificado para Supabase
const noChanges = (itemsParaUpsert.length === 0);

return [{
  json: {
    _no_changes: noChanges,
    batch_json_str: JSON.stringify(itemsParaUpsert).replace(/'/g, "''"),
    reporte_inconsistencias: reportFilePath,
    _stats: {
      total_buckets: buckets.size,
      omitidos: omitidosCount,
      modificados: itemsParaUpsert.length,
      normalizaciones_fuzzy: fuzzyMatchesCount,
      inconsistencias: inconsistencias.length,
      reporte_inconsistencias: reportFilePath
    }
  }
}];

const pData = $('3. Normalizar, Rollup y Diffing Cero Reimpresión').first()?.json || {};
const stats = pData._stats || {};
const noChanges = pData._no_changes === true;

const totalModificados = noChanges ? 0 : (stats.modificados || 0);
const totalOmitidos = stats.omitidos || 0;
const totalBuckets = stats.total_buckets || (totalModificados + totalOmitidos);
const pctAhorro = totalBuckets > 0 ? ((totalOmitidos / totalBuckets) * 100).toFixed(1) + '%' : '100%';

return [{
  json: {
    estado: '✅ Extracción de Kilómetros y Diffing completados',
    total_buckets_mensuales: totalBuckets,
    registros_inyectados_actualizados: totalModificados,
    registros_preexistentes_omitidos: totalOmitidos,
    ahorro_log_queries: pctAhorro,
    inconsistencias_detectadas: stats.inconsistencias || 0,
    reporte_inconsistencias: stats.reporte_inconsistencias || 'C:\\Users\\Matias Rodriguez\\Documents\\reportes\\km',
    destino: 'public.choferes_km_mensual',
    timestamp: new Date().toISOString()
  }
}];

return [{ 
  json: { 
    status: 'IDLE_EMPTY_QUEUE', 
    message: 'Cola eor_sync_queue sin mutaciones pendientes (<40 B egress, 0 llamadas a Google API)', 
    total_pendientes: 0, 
    timestamp: new Date().toISOString() 
  } 
}];

const raw = $json.stdout || '';
let response = {};
try {
  const firstBrace = raw.indexOf('{');
  const lastBrace = raw.lastIndexOf('}');
  if (firstBrace !== -1 && lastBrace !== -1) {
    response = JSON.parse(raw.substring(firstBrace, lastBrace + 1));
  } else if ($json.stats) {
    response = $json;
  }
} catch (e) {
  response = { success: false, error: 'Falla parseando salida del worker', raw };
}

const stats = response.stats || {};
const completed = stats.completadosEnSheets || stats.completed || 0;
const failed = stats.fallidosConReintento || stats.failed || 0;
const googleApiRequests = stats.peticionesGoogleApi || stats.googleApiRequests || 0;
const batchRequestsSent = stats.lotesBatchUpdate || stats.batchRequestsSent || 0;
const egressBytes = stats.egressBytes || 0;
const executionTimeMs = stats.duracionMs || stats.executionTimeMs || 0;
const wipedRows = stats.filasWipeadas || stats.wipedRows || 0;
const details = stats.detalles || stats.details || [];

return [{
  json: {
    syncSuccess: response.success,
    dryRun: response.dryRun || false,
    batchLimit: response.batchLimit || 50,
    totalPending: stats.totalPending || 0,
    mutacionesProcesadas: stats.mutacionesProcesadas || stats.individualMutations || 0,
    completadosEnSheets: completed,
    fallidosConReintento: failed,
    peticionesGoogleApi: googleApiRequests,
    lotesBatchUpdate: batchRequestsSent,
    egressBytes: egressBytes,
    egressFormatted: egressBytes < 1024 ? egressBytes + ' B' : (egressBytes / 1024).toFixed(2) + ' KB',
    duracionMs: executionTimeMs,
    filasWipeadas: wipedRows,
    detalles: details,
    timestamp: new Date().toISOString()
  }
}];

const data = $input.first().json;
console.log('⚡ [n8n Sync Worker] Impresión de datos hacia Google Sheets:');
console.log(`   • Modo: ${data.dryRun ? 'DRY-RUN (Simulación)' : 'PRODUCCIÓN (Escritura Real)'}`);
console.log(`   • Completados en Sheets: ${data.completadosEnSheets}`);
console.log(`   • Peticiones Google API: ${data.peticionesGoogleApi}`);
console.log(`   • Lotes BatchUpdate: ${data.lotesBatchUpdate}`);
console.log(`   • Egress transferido: ${data.egressFormatted}`);
console.log(`   • Tiempo de ejecución: ${data.duracionMs} ms`);

return [{
  json: {
    estado: data.syncSuccess ? '✅ Impresión de datos en Google Sheets completada' : '❌ Error en impresión',
    modo: data.dryRun ? 'DRY-RUN (Simulación)' : 'PRODUCCIÓN (Escritura Real)',
    total_pendientes: data.totalPending,
    mutaciones_procesadas: data.mutacionesProcesadas,
    completados_en_sheets: data.completadosEnSheets,
    fallidos_con_reintento: data.fallidosConReintento,
    peticiones_google_api: data.peticionesGoogleApi,
    lotes_batch_update: data.lotesBatchUpdate,
    egress_transferido: data.egressFormatted,
    filas_wipeadas_24h: data.filasWipeadas,
    tiempo_ejecucion_ms: data.duracionMs,
    detalles: data.detalles,
    timestamp: data.timestamp
  }
}];

function restoreEnie(str) {
  if (!str) return { restored: '', hadHashOrMojibake: false };
  const orig = String(str).trim();
  const hadHashOrMojibake = /#|Ã‘|Ã±|\uFFFD/.test(orig);
  const restored = orig
    .replace(/Ã‘|Ã±|\uFFFD/g, 'Ñ')
    .replace(/#/g, 'Ñ')
    .replace(/\s+/g, ' ')
    .trim();
  return { restored, hadHashOrMojibake };
}

function sanitizeNameAscii(str) {
  if (!str) return '';
  return restoreEnie(str).restored
    .replace(/[ñÑ]/g, 'N')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toUpperCase()
    .replace(/[^A-Z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function getSignificantTokens(str) {
  const stopWords = new Set(['DE', 'DEL', 'LA', 'LAS', 'LOS', 'Y', 'SAN', 'SANTA']);
  return sanitizeNameAscii(str).split(' ').filter(t => t && !stopWords.has(t));
}

function sortedTokenKey(str) {
  return getSignificantTokens(str).slice().sort().join(' ');
}

function levenshtein(a, b) {
  if (a === b) return 0;
  const m = a.length, n = b.length;
  if (m === 0) return n;
  if (n === 0) return m;
  let prev = new Array(n + 1);
  let curr = new Array(n + 1);
  for (let j = 0; j <= n; j++) prev[j] = j;
  for (let i = 1; i <= m; i++) {
    curr[0] = i;
    const ca = a.charCodeAt(i - 1);
    for (let j = 1; j <= n; j++) {
      const cost = ca === b.charCodeAt(j - 1) ? 0 : 1;
      curr[j] = Math.min(prev[j] + 1, curr[j - 1] + 1, prev[j - 1] + cost);
    }
    const tmp = prev; prev = curr; curr = tmp;
  }
  return prev[n];
}

function tokenSimilarity(t1, t2) {
  if (t1 === t2) return 1.0;
  const maxLen = Math.max(t1.length, t2.length);
  return maxLen === 0 ? 1.0 : 1.0 - levenshtein(t1, t2) / maxLen;
}

const KNOWN_ALIASES = {
  'ACUNA SANTIAGO': 'ACUÑA RAFAEL SANTIAGO',
  'AGUERO ALEXIS': 'AGUERO ALEXIS DAMIAN',
  'ALANIZ CRISTIAN PAULO': 'ALANIZ CRISTIAN PAULO',
  'MENDOZA ERWIN GONZALO': 'MENDOZA REYES ERWIN GONZALO',
  'POO NARVAEZ JAIRO': 'POO NARVAEZ JAIRO BERNABE',
  'SANDOVAL DARIO': 'SANDOVAL REYES CRISTIAN EDUARDO',
  'LEONARDO ARIEL GUEVARA': 'GUEVARA LEONARDO A',
  'GUEVARA LEONARDO ARIEL': 'GUEVARA LEONARDO A',
  'RAMOS GONZALO DAVID': 'RAMOS DAVID GONZALO',
  'RAMOS DAVID GONZALO': 'RAMOS DAVID GONZALO'
};

function parseFechaFlexible(str) {
  if (!str) return null;
  const s = String(str).trim();
  if (!s || s === '-' || s.toLowerCase() === 'ok' || s.startsWith('#')) return null;

  const slashParts = s.split(/[\/\-]/);
  if (slashParts.length === 3 && !isNaN(slashParts[0]) && !isNaN(slashParts[1])) {
    let d = parseInt(slashParts[0], 10);
    let m = parseInt(slashParts[1], 10);
    let y = parseInt(slashParts[2], 10);
    if (y < 100) y += 2000;
    if (d > 0 && d <= 31 && m > 0 && m <= 12 && y > 1900 && y < 2100) {
      return `${y}-${String(m).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
    }
  }

  const textParts = s.split(/\s+/);
  if (textParts.length === 3) {
    const d = parseInt(textParts[0], 10);
    const mStr = textParts[1].toLowerCase().slice(0, 3);
    let y = parseInt(textParts[2], 10);
    if (y < 100) y += 2000;
    const monthMap = {
