};

function parseFechaFlexible(str) {
  if (!str) return null;
  const s = String(str).trim();
  if (!s || s === '-' || s.toLowerCase() === 'ok' || s.startsWith('#')) return null;

  const slashParts = s.split(/[\/\-]/);
  if (slashParts.length === 3 && !isNaN(slashParts[0]) && !isNaN(slashParts[1])) {
    let d = parseInt(slashParts[0], 10);
    let m = parseInt(slashParts[1], 10);
    let y = parseInt(slashParts[2], 10);
    if (y < 100) y += 2000;
    if (d > 0 && d <= 31 && m > 0 && m <= 12 && y > 1900 && y < 2100) {
      return `${y}-${String(m).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
    }
  }

  const textParts = s.split(/\s+/);
  if (textParts.length === 3) {
    const d = parseInt(textParts[0], 10);
    const mStr = textParts[1].toLowerCase().slice(0, 3);
    let y = parseInt(textParts[2], 10);
    if (y < 100) y += 2000;
    const monthMap = {
      ene: 1, jan: 1, feb: 2, mar: 3, abr: 4, apr: 4,
      may: 5, jun: 6, jul: 7, ago: 8, aug: 8, sep: 9, set: 9,
      oct: 10, nov: 11, dic: 12, dec: 12
    };
    const m = monthMap[mStr];
    if (d > 0 && d <= 31 && m && y > 1900 && y < 2100) {
      return `${y}-${String(m).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
    }
  }

  if (/^\d{4}-\d{2}-\d{2}/.test(s)) return s.substring(0, 10);
  return null;
}

function cleanDni(val) {
  if (!val) return null;
  const digits = String(val).replace(/\D/g, '');
  if (digits.length === 11) return digits.substring(2, 10);
  if (digits.length >= 7 && digits.length <= 8) return digits;
  return digits || null;
}

function cleanCuil(val) {
  if (!val) return null;
  const digits = String(val).replace(/\D/g, '');
  if (digits.length === 11) {
    return `${digits.substring(0, 2)}-${digits.substring(2, 10)}-${digits.substring(10)}`;
  }
  return String(val).trim() || null;
}

function normText(s) {
  return String(s || '').trim().replace(/\r?\n|\r/g, ' ').replace(/\s+/g, ' ');
}

const pgData = $('1. Pre-fetch Choferes, Unidades y Observaciones (Supabase)').first()?.json || {};
const dbChoferes = Array.isArray(pgData.choferes) ? pgData.choferes : [];
const dbUnidades = Array.isArray(pgData.unidades) ? pgData.unidades : [];
const preexistentes = Array.isArray(pgData.preexistentes) ? pgData.preexistentes : [];
const rows = $input.all().map(i => i.json);

const unidadMap = new Map();
for (const u of dbUnidades) {
  if (u.tr_patente) unidadMap.set(u.tr_patente.toUpperCase().trim(), u.unidad_id);
  if (u.semi_patente) unidadMap.set(u.semi_patente.toUpperCase().trim(), u.unidad_id);
  if (u.n_ute) unidadMap.set(u.n_ute.toUpperCase().trim(), u.unidad_id);
}

const preMap = new Map();
preexistentes.forEach(obs => {
  const k = `${obs.chofer_id}__${obs.fecha}__${normText(obs.evento).toLowerCase()}__${normText(obs.obs_evento).toLowerCase()}`;
  preMap.set(k, obs);
});

const bySanitized = new Map();
const bySortedTokens = new Map();
const byTokensList = [];

for (const c of dbChoferes) {
  if (!c || !c.nombre) continue;
  const san = sanitizeNameAscii(c.nombre);
  const sKey = sortedTokenKey(c.nombre);
  const tokens = getSignificantTokens(c.nombre);
  bySanitized.set(san, c);
  bySortedTokens.set(sKey, c);
  byTokensList.push({ chofer: c, tokens, tokenSet: new Set(tokens), mainSurname: tokens[0] });
}

function resolveChoferParticion1(rawName) {
  if (!rawName) return null;
  const { restored } = restoreEnie(rawName);
  const san = sanitizeNameAscii(restored);
  if (!san || san.length < 3 || san.startsWith('NO IDENTIFICADO') || san.startsWith('TOTAL') || san === 'CHOFER' || san.startsWith('PERSONAL')) return null;

  if (bySanitized.has(san)) return bySanitized.get(san);
  if (KNOWN_ALIASES[san]) {
    const aliasT = sanitizeNameAscii(KNOWN_ALIASES[san]);
    if (bySanitized.has(aliasT)) return bySanitized.get(aliasT);
  }
  const sKey = sortedTokenKey(restored);
  if (bySortedTokens.has(sKey)) return bySortedTokens.get(sKey);

  const kTokens = getSignificantTokens(restored);
  const kSet = new Set(kTokens);
  if (kTokens.length >= 2) {
    const cands = byTokensList.filter(it => {
      const surnameMatch = it.mainSurname === kTokens[0] || tokenSimilarity(it.mainSurname, kTokens[0]) >= 0.85;
      if (!surnameMatch) return false;
      const kInIt = kTokens.every(t => it.tokenSet.has(t) || Array.from(it.tokenSet).some(itT => tokenSimilarity(t, itT) >= 0.85));
      const itInK = it.tokens.every(t => kSet.has(t) || Array.from(kSet).some(kt => tokenSimilarity(t, kt) >= 0.85));
      return kInIt || itInK;
    });
    if (cands.length === 1) return cands[0].chofer;
  }

  let bestCand = null, bestSim = 0;
  for (const item of byTokensList) {
    const surnameSim = Math.max(...kTokens.map(kt => tokenSimilarity(item.mainSurname, kt)));
    if (surnameSim < 0.72) continue;
    const shorter = kTokens.length <= item.tokens.length ? kTokens : item.tokens;
    const longer = kTokens.length <= item.tokens.length ? item.tokens : kTokens;
    if (shorter.length === 0) continue;
    let sumSim = 0;
    for (const st of shorter) {
      let maxS = 0;
      for (let i = 0; i < longer.length; i++) {
        const s = tokenSimilarity(st, longer[i]);
        if (s > maxS) maxS = s;
      }
      sumSim += maxS;
    }
    const score = sumSim / shorter.length;
    if (score > bestSim) { bestSim = score; bestCand = item.chofer; }
  }
  if (bestSim >= 0.80 && bestCand) return bestCand;
  return null;
}

const nuevasEntradas = [];
const cambiosActualizados = [];
let sinCambiosOmitidos = 0;
let procesadosCount = 0;
let descartadosCount = 0;

for (let idx = 0; idx < rows.length; idx++) {
  const row = rows[idx];
  const admin = normText(row['Administrador\nde Carga'] ?? row['Administrador de Carga'] ?? row.admin ?? row['0'] ?? '');
  const rawNom = normText(row['Chofer'] ?? row.chofer ?? row['1'] ?? '');
  const rawFecha = normText(row['Fecha'] ?? row.fecha ?? row['2'] ?? '');
  const rawUnidad = normText(row['Unidad'] ?? row.unidad ?? row['3'] ?? '');
  const evento = normText(row['Evento'] ?? row.evento ?? row['4'] ?? '');
  const obsEvento = normText(row['Obs. Evento'] ?? row['Obs. Evento'] ?? row.obs_evento ?? row['5'] ?? '');
  const estado = normText(row['Estado'] ?? row.estado ?? row['6'] ?? '');
  const obsEstado = normText(row['Obs. Estado'] ?? row['Obs. Estado'] ?? row.obs_estado ?? row['7'] ?? '');

  if (!rawNom && !evento && !obsEvento) continue;

  const chofer = resolveChoferParticion1(rawNom);
  if (!chofer) {
    descartadosCount++;
    continue;
  }
  procesadosCount++;

  const fechaNorm = parseFechaFlexible(rawFecha);
  const unidadId = rawUnidad ? (unidadMap.get(rawUnidad.toUpperCase().replace(/\s+/g, '')) || null) : null;

  const businessKey = `${chofer.id}__${fechaNorm}__${evento.toLowerCase()}__${obsEvento.toLowerCase()}`;
  const pre = preMap.get(businessKey);

  const record = {
    chofer_id: chofer.id,
    fecha: fechaNorm,
    evento: evento || null,
    obs_evento: obsEvento || null,
    estado: estado || null,
    obs_estado: obsEstado || null,
    admin_carga: admin || null,
    unidad_id: unidadId
  };

  if (!pre) {
    nuevasEntradas.push(record);
    preMap.set(businessKey, { ...record, id: 'temp-batch' });
  } else {
    const sameEstado = normText(pre.estado) === normText(estado);
    const sameObsEstado = normText(pre.obs_estado) === normText(obsEstado);
    const sameAdmin = normText(pre.admin_carga) === normText(admin);
    const sameUnidad = (pre.unidad_id || null) === (unidadId || null);

    if (sameEstado && sameObsEstado && sameAdmin && sameUnidad) {
      sinCambiosOmitidos++;
    } else {
      cambiosActualizados.push({
        id: pre.id,
        ...record
      });
    }
  }
}

const hasChanges = (nuevasEntradas.length > 0 || cambiosActualizados.length > 0);
const statsObj = {
  total_sheet: rows.length,
  procesables_particion_1: procesadosCount,
  descartados_no_particion_1: descartadosCount,
  nuevas_entradas: nuevasEntradas.length,
  cambios_actualizados: cambiosActualizados.length,
  sin_cambios_omitidos: sinCambiosOmitidos
};

return [{
  json: {
    _no_changes: !hasChanges,
    inserts_json_str: JSON.stringify(nuevasEntradas).replace(/'/g, "''"),
    updates_json_str: JSON.stringify(cambiosActualizados).replace(/'/g, "''"),
    _stats: statsObj
  }
}];

const stats = $('3. Fuzzy Partición 1 y Diffing O(1) (Observaciones)').first()?.json?._stats || {};
return [{
