// NODO CODE: FILTRAR, NORMALIZAR Y DIFFING PAREOS DIARIOS Y NOTIFICACIÓN DE DESUNIONES
const rows = $input.all().map(i => i.json);

// 1. Obtener día operativo de hoy (Zona horaria Argentina UTC-3)
let diaHoy;
try {
  const config = $('⚙️ Configuración: Movimientos').first()?.json || {};
  if (config.dia || config.dia_operativo) {
    diaHoy = parseInt(config.dia || config.dia_operativo, 10);
  }
} catch (e) {}

if (!diaHoy || isNaN(diaHoy)) {
  const fechaAr = new Date().toLocaleDateString('es-AR', { timeZone: 'America/Argentina/Buenos_Aires' });
  diaHoy = parseInt(fechaAr.split('/')[0], 10);
}

// Bloques diarios de 13 cols arrancan en Col 27 (0-based) para día 1
const targetColIdx = 28 + 13 * (diaHoy - 1);
const keyChoferPrimary = `col_${targetColIdx}`;
const keyChoferFallback = `col_${targetColIdx - 1}`;

// 2. Pre-fetch Supabase
const pgData = $('1. Pre-fetch Movimientos Activos y Catálogo (Supabase)').first()?.json || {};
const dbMovimientos = Array.isArray(pgData.movimientos_activos) ? pgData.movimientos_activos : [];
const dbChoferes = Array.isArray(pgData.choferes) ? pgData.choferes : [];
const dbUnidades = Array.isArray(pgData.unidades) ? pgData.unidades : [];

const movActivosPorUnidad = new Map();
const movActivosPorChofer = new Map();
for (const m of dbMovimientos) {
  if (m && m.id_unidad) movActivosPorUnidad.set(m.id_unidad, m);
  if (m && m.id_chofer) movActivosPorChofer.set(m.id_chofer, m);
}

function normText(str) {
  if (!str) return '';
  return String(str)
    .replace(/Ã‘|Ã±|\uFFFD/g, 'Ñ')
    .replace(/#/g, 'Ñ')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toUpperCase()
    .replace(/[^A-Z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

const choferesMap = new Map();
for (const c of dbChoferes) {
  if (c && c.nombre) choferesMap.set(normText(c.nombre), c);
}

const unidadPorTractor = new Map();
const unidadPorSemi = new Map();
const unidadPorUte = new Map();

for (const u of dbUnidades) {
  if (!u) continue;
  if (u.tr_patente) unidadPorTractor.set(normText(u.tr_patente), u);
  if (u.semi_patente) unidadPorSemi.set(normText(u.semi_patente), u);
  if (u.n_ute) {
    const cleanUte = String(u.n_ute).replace(/[^0-9]/g, '');
    if (cleanUte) unidadPorUte.set(cleanUte, u);
  }
}

const blacklist = new Set([
  'TRACTOR', 'SEMI', 'CHOFER', 'NOMBRE', 'APELLIDO', '1', '0', '-', 'S/A', 'VACANTE',
  'FECHA', 'N°', 'CISTERNADO', 'TOTAL', 'LIVIANO', 'METANOL', 'CAMPO', 'GLP', 'SOCIO', 'OCTUBRE',
  'NO DISPONIBLE', 'REPARACIÓN', 'REPARACION', 'MANTENIMIENTO', 'EN VIAJE', 'DISPO', 'DIAG',
  'DESCANSO', 'FRANCO', 'VACACIONES', 'LICENCIA', 'GUARDIA', 'EN GESTION', 'DISPONIBLE'
]);

// 3. Procesar Filas de Google Sheets con Deduplicación en Memoria
const desunirSet = new Set();
const desunionesAudit = [];
let desunionesNoOpCount = 0;

const mutacionesMap = new Map(); // id_unidad -> { id_unidad, id_chofer }
const choferAsignadoAUnidad = new Map(); // id_chofer -> id_unidad
const colisionesChoferAudit = [];
const nuevosPareosAudit = [];
const reasignacionesAudit = [];
let pareosIdenticosCount = 0;

let currentServicio = 'GENERAL';
let totalFilasEvaluadas = 0;

for (const row of rows) {
  if (!row) continue;

  const colA = String(row.col_1 || row.LIVIANO || row.col_0 || '').trim();
  const colC = String(row.col_3 || row.col_2 || '').trim(); // N° UTE
  const colE = String(row.col_5 || row.col_4 || '').trim(); // Tractor
  const colF = String(row.col_6 || row.col_5 || '').trim(); // Semi

  if (colA && !colC && !colE && !colF) {
    const upA = colA.toUpperCase();
    if (!upA.includes('FECHA') && !upA.includes('N°') && !upA.includes('OCTUBRE') && !upA.includes('SEPTIEMBRE')) {
      currentServicio = upA;
    }
    continue;
  }

  const tractor = colE.toUpperCase().replace(/\s+/g, '');
  const semi = colF.toUpperCase().replace(/\s+/g, '');
  const nUte = colC.replace(/[^0-9]/g, '');

  if (!tractor && !semi && !nUte) continue;
  if (tractor === 'TRACTOR' || semi === 'SEMI') continue;

  let targetUnit = null;
  if (tractor && unidadPorTractor.has(normText(tractor))) {
    targetUnit = unidadPorTractor.get(normText(tractor));
  } else if (semi && unidadPorSemi.has(normText(semi))) {
    targetUnit = unidadPorSemi.get(normText(semi));
  } else if (nUte && unidadPorUte.has(nUte)) {
    targetUnit = unidadPorUte.get(nUte);
  }

  if (!targetUnit) continue;
  totalFilasEvaluadas++;

  let rawChofer = String(row[keyChoferPrimary] !== undefined ? row[keyChoferPrimary] : (row[keyChoferFallback] || '')).trim();

  const esDesunion = (!rawChofer || rawChofer === '1' || rawChofer === '0' || rawChofer === '-' ||
                      rawChofer.toUpperCase() === 'S/A' || rawChofer.toUpperCase() === 'VACANTE' ||
                      rawChofer.length < 3 || !/[a-zA-Z]/.test(rawChofer) || blacklist.has(rawChofer.toUpperCase()));

  const movActivo = movActivosPorUnidad.get(targetUnit.id);

  if (esDesunion) {
    if (movActivo) {
      desunirSet.add(targetUnit.id);
      desunionesAudit.push({
        n_ute: targetUnit.n_ute || nUte || 'S/N',
        tractor: targetUnit.tr_patente || tractor || 'S/T',
        semi: targetUnit.semi_patente || semi || 'S/S',
        chofer_desvinculado: movActivo.chofer_nombre || 'DESCONOCIDO',
        motivo_sheet: rawChofer ? `Carácter '${rawChofer}'` : 'Celda vacía / Libre',
        dia_operativo: diaHoy
      });
    } else {
      desunionesNoOpCount++;
    }
  } else {
    const cleanChoferName = normText(rawChofer);
    let choferMatch = choferesMap.get(cleanChoferName);

    if (!choferMatch) {
      const tokens = cleanChoferName.split(' ').filter(t => t.length > 2);
      for (const [k, c] of choferesMap.entries()) {
        if (tokens.every(t => k.includes(t))) {
          choferMatch = c;
          break;
        }
      }
    }

    if (choferMatch) {
      if (movActivo && movActivo.id_chofer === choferMatch.id) {
        pareosIdenticosCount++;
      } else {
        if (choferAsignadoAUnidad.has(choferMatch.id)) {
          // COLISIÓN DETECTADA: Chofer duplicado en la misma fecha en Google Sheets (ignorar asignación secundaria)
          const asignadoPrevio = choferAsignadoAUnidad.get(choferMatch.id);
          colisionesChoferAudit.push({
            chofer: choferMatch.nombre,
            n_ute_asignado: asignadoPrevio.n_ute || 'S/N',
            unidad_id_asignada: asignadoPrevio.id,
            n_ute_conflicto: targetUnit.n_ute || nUte || 'S/N',
            unidad_id_conflicto: targetUnit.id,
            dia_operativo: diaHoy,
            motivo: 'CHOFER_DUPLICADO_EN_HOJA_IGNORADO_SEGUNDO'
          });
        } else {
          // Mutación de pareo (Deduplicada estrictamente por unidad_id y por chofer_id)
          mutacionesMap.set(targetUnit.id, {
            id_unidad: targetUnit.id,
            id_chofer: choferMatch.id
          });
          choferAsignadoAUnidad.set(choferMatch.id, {
            id: targetUnit.id,
            n_ute: targetUnit.n_ute || nUte || 'S/N'
          });

          if (movActivo) {
            reasignacionesAudit.push({
              n_ute: targetUnit.n_ute || nUte || 'S/N',
              tractor: targetUnit.tr_patente || tractor || 'S/T',
              semi: targetUnit.semi_patente || semi || 'S/S',
              chofer_anterior: movActivo.chofer_nombre,
              chofer_nuevo: choferMatch.nombre,
              dia_operativo: diaHoy
            });
          } else {
            nuevosPareosAudit.push({
              n_ute: targetUnit.n_ute || nUte || 'S/N',
              tractor: targetUnit.tr_patente || tractor || 'S/T',
              semi: targetUnit.semi_patente || semi || 'S/S',
              chofer: choferMatch.nombre,
              dia_operativo: diaHoy
            });
          }
        }
      }
    }
  }
}

const desunirArr = Array.from(desunirSet);
const pareosArr = Array.from(mutacionesMap.values());
const noChanges = (desunirArr.length === 0 && pareosArr.length === 0);

return [{
  json: {
    _no_changes: noChanges,
    desunir_unidades_json_str: JSON.stringify(desunirArr),
    upserts_json_str: JSON.stringify(pareosArr),
    _stats: {
      total_filas_sheet: rows.length,
      total_unidades_evaluadas: totalFilasEvaluadas,
      desuniones_reales: desunirArr.length,
      desuniones_no_op: desunionesNoOpCount,
      pareos_identicos_omitidos: pareosIdenticosCount,
      pareos_mutados: pareosArr.length,
      nuevos_pareos: nuevosPareosAudit.length,
      reasignaciones: reasignacionesAudit.length,
      colisiones_chofer: colisionesChoferAudit.length
    },
    _notificaciones: {
