    else if (currentServicio === 'ABASTECEDORES') rawUte = rawUte + '-C';
  }

  const rawTractor = String(row['Tractor'] || row.col_5 || row['4'] || '').replace(/[^A-Z0-9]/g, '').toUpperCase();
  const rawSemi = String(row['SEMI'] || row.col_6 || '').replace(/[^A-Z0-9]/g, '').toUpperCase();

  const validTractor = (rawTractor.length >= 5 && rawTractor.length <= 8 && !/^\d+$/.test(rawTractor) && !blacklist.has(rawTractor)) ? rawTractor : null;
  const validSemi = (rawSemi.length >= 5 && rawSemi.length <= 8 && !/^\d+$/.test(rawSemi) && !blacklist.has(rawSemi) && rawSemi !== validTractor) ? rawSemi : null;

  if (!validTractor && !validSemi && !rawUte) continue;
  totalEvaluadas++;

  let ex = null;
  if (rawUte && uniByUte.has(rawUte)) ex = uniByUte.get(rawUte);
  else if (validTractor && uniByTractor.has(validTractor)) ex = uniByTractor.get(validTractor);
  else if (validSemi && uniBySemi.has(validSemi)) ex = uniBySemi.get(validSemi);

  if (!ex) {
    nuevasCount++;
    deltaBatch.push({
      n_ute: rawUte,
      patente_tractor: validTractor,
      patente_semi: validSemi,
      servicio_nombre: currentServicio
    });
  } else {
    const sameT = (ex.tr_patente || null) === validTractor;
    const sameS = (ex.semi_patente || null) === validSemi;
    const sameUte = (!rawUte && !ex.n_ute) || (String(ex.n_ute).trim() === rawUte);

    if (sameT && sameS && sameUte) {
      omitidasCount++;
    } else {
      mutadasCount++;
      deltaBatch.push({
        n_ute: rawUte || ex.n_ute,
        patente_tractor: validTractor,
        patente_semi: validSemi,
        servicio_nombre: currentServicio
      });
    }
  }
}

return [{
  json: {
    _no_changes: deltaBatch.length === 0,
    batch_json_str: JSON.stringify(deltaBatch),
    _stats: {
      total_unidades_evaluadas: totalEvaluadas,
      nuevas: nuevasCount,
      mutadas: mutadasCount,
      omitidas_identicas: omitidasCount
    }
  }
}];

parameters.query:
DO $$
DECLARE
  r JSONB;
  v_trac_id UUID;
  v_semi_id UUID;
  v_srv_id UUID;
  v_unit_id UUID;
  v_curr_trac UUID;
  v_curr_semi UUID;
  v_ute TEXT;
  v_pat_trac TEXT;
  v_pat_semi TEXT;
  v_srv_name TEXT;
BEGIN
  IF '{{ $json._no_changes || "false" }}' = 'true' THEN
    RETURN;
  END IF;

  FOR r IN SELECT * FROM jsonb_array_elements('{{ $json.batch_json_str }}'::jsonb)
  LOOP
    v_trac_id := NULL;
    v_semi_id := NULL;
    v_srv_id := NULL;
    v_unit_id := NULL;
    v_curr_trac := NULL;
    v_curr_semi := NULL;

    v_ute := NULLIF(TRIM(r->>'n_ute'), '');
    v_pat_trac := TRIM(COALESCE(r->>'patente_tractor', ''));
    v_pat_semi := TRIM(COALESCE(r->>'patente_semi', ''));
    v_srv_name := TRIM(COALESCE(r->>'servicio_nombre', ''));

    IF v_pat_trac <> '' THEN
      SELECT id INTO v_trac_id FROM public.tractores WHERE UPPER(patente) = UPPER(v_pat_trac) LIMIT 1;
    END IF;

    IF v_pat_semi <> '' THEN
      SELECT id INTO v_semi_id FROM public.semis WHERE UPPER(patente) = UPPER(v_pat_semi) LIMIT 1;
    END IF;

    IF v_srv_name <> '' THEN
      INSERT INTO public.servicios_unidades (denominacion)
      VALUES (v_srv_name)
      ON CONFLICT (denominacion) DO NOTHING;

      SELECT id INTO v_srv_id FROM public.servicios_unidades WHERE UPPER(denominacion) = UPPER(v_srv_name) LIMIT 1;
    END IF;

    IF v_ute IS NOT NULL THEN
      SELECT id, tractor_id, semi_id INTO v_unit_id, v_curr_trac, v_curr_semi 
      FROM public.unidades WHERE n_ute = v_ute LIMIT 1;
    ELSE
      IF v_trac_id IS NOT NULL THEN
        SELECT id, tractor_id, semi_id INTO v_unit_id, v_curr_trac, v_curr_semi 
        FROM public.unidades WHERE tractor_id = v_trac_id AND (n_ute IS NULL OR n_ute = '') LIMIT 1;
      END IF;

      IF v_unit_id IS NULL AND v_semi_id IS NOT NULL THEN
        SELECT id, tractor_id, semi_id INTO v_unit_id, v_curr_trac, v_curr_semi 
        FROM public.unidades WHERE semi_id = v_semi_id AND (n_ute IS NULL OR n_ute = '') LIMIT 1;
      END IF;
    END IF;

    IF v_trac_id IS NOT NULL THEN
      UPDATE public.unidades SET tractor_id = NULL WHERE tractor_id = v_trac_id AND (v_unit_id IS NULL OR id <> v_unit_id);
    END IF;

    IF v_semi_id IS NOT NULL THEN
      UPDATE public.unidades SET semi_id = NULL WHERE semi_id = v_semi_id AND (v_unit_id IS NULL OR id <> v_unit_id);
    END IF;

    IF v_unit_id IS NOT NULL THEN
      UPDATE public.unidades
      SET n_ute = COALESCE(v_ute, unidades.n_ute),
          tractor_id = COALESCE(v_trac_id, unidades.tractor_id),
          semi_id = COALESCE(v_semi_id, unidades.semi_id),
          servicio_id = COALESCE(v_srv_id, unidades.servicio_id),
          fecha_acople = CASE 
            WHEN (v_trac_id IS DISTINCT FROM v_curr_trac OR v_semi_id IS DISTINCT FROM v_curr_semi) THEN NOW()
            ELSE unidades.fecha_acople 
          END
      WHERE id = v_unit_id;
    ELSE
      INSERT INTO public.unidades (n_ute, tractor_id, semi_id, servicio_id, fecha_acople, estado)
      VALUES (v_ute, v_trac_id, v_semi_id, v_srv_id, NOW(), 'disponible');
    END IF;
  END LOOP;
END $$;

