  'ALEXIS DAMIAN AGUERO': 'AGUERO ALEXIS',
  'PAULO CRISTIAN ALANIZ': 'ALANIZ CRISTIAN PAULO'
};

function restoreEnie(str) {
  if (!str) return { restored: '', hadHashOrMojibake: false };
  const orig = String(str).trim();
  const hadHashOrMojibake = /#|Ã‘|Ã±|\uFFFD/.test(orig);
  const restored = orig
    .replace(/Ã‘|Ã±|\uFFFD/g, 'Ñ')
    .replace(/#/g, 'Ñ')
    .replace(/\s+/g, ' ')
    .trim();
  return { restored, hadHashOrMojibake };
}

function sanitizeNameAscii(str) {
  if (!str) return '';
  return restoreEnie(str).restored
    .replace(/[ñÑ]/g, 'N')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toUpperCase()
    .replace(/[^A-Z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function getSignificantTokens(str) {
  const stopWords = new Set(['DE', 'DEL', 'LA', 'LAS', 'LOS', 'Y']);
  return sanitizeNameAscii(str).split(' ').filter(t => t && !stopWords.has(t));
}

function sortedTokenKey(str) {
  return getSignificantTokens(str).slice().sort().join(' ');
}

function levenshtein1D(a, b) {
  if (a === b) return 0;
  const m = a.length, n = b.length;
  if (m === 0) return n;
  if (n === 0) return m;
  let prev = new Array(n + 1);
  let curr = new Array(n + 1);
  for (let j = 0; j <= n; j++) prev[j] = j;
  for (let i = 1; i <= m; i++) {
    curr[0] = i;
    const ca = a.charCodeAt(i - 1);
    for (let j = 1; j <= n; j++) {
      const cost = ca === b.charCodeAt(j - 1) ? 0 : 1;
      curr[j] = Math.min(prev[j] + 1, curr[j - 1] + 1, prev[j - 1] + cost);
    }
    const tmp = prev; prev = curr; curr = tmp;
  }
  return prev[n];
}

function tokenSimilarity(t1, t2) {
  if (t1 === t2) return 1.0;
  const maxLen = Math.max(t1.length, t2.length);
  return maxLen === 0 ? 1.0 : 1.0 - levenshtein1D(t1, t2) / maxLen;
}

const bySanitized = new Map();
const bySortedTokens = new Map();
const byTokensList = [];

for (const c of dbChoferes) {
  if (!c || !c.nombre) continue;
  const san = sanitizeNameAscii(c.nombre);
  const sKey = sortedTokenKey(c.nombre);
  const tokens = getSignificantTokens(c.nombre);
  bySanitized.set(san, c);
  bySortedTokens.set(sKey, c);
  byTokensList.push({ chofer: c, tokens, tokenSet: new Set(tokens), mainSurname: tokens[0] });
}

const resolutionCache = new Map();

function resolveChoferParticion1(rawKeeperName) {
  const cacheKey = String(rawKeeperName || '').trim();
  if (resolutionCache.has(cacheKey)) {
    return resolutionCache.get(cacheKey);
  }

  const { restored, hadHashOrMojibake } = restoreEnie(rawKeeperName);
  const san = sanitizeNameAscii(restored);
  if (!san || san.startsWith('NO IDENTIFICADO') || san === 'CHOFER') {
    const r0 = {
      matched: false, chofer: null, restoredName: restored, hadHashOrMojibake,
      rule: 'FILA_NO_IDENTIFICADO_O_ENCABEZADO', similarityPct: 0, bestRejectedCandidate: null
    };
    resolutionCache.set(cacheKey, r0);
    return r0;
  }

  const suffixEnie = hadHashOrMojibake ? ' + REEMPLAZO_#_A_Ñ' : '';
  if (bySanitized.has(san)) {
    const r1 = {
      matched: true, chofer: bySanitized.get(san), restoredName: restored, hadHashOrMojibake,
      rule: hadHashOrMojibake ? 'REEMPLAZO_#_A_Ñ_EXACTO' : 'EXACT_DIRECT', similarityPct: 100
    };
    resolutionCache.set(cacheKey, r1);
    return r1;
  }

  if (ALIAS_KEEPER_TO_CANON[san]) {
    const found = bySanitized.get(sanitizeNameAscii(ALIAS_KEEPER_TO_CANON[san]));
    if (found) {
      const r2 = {
        matched: true, chofer: found, restoredName: restored, hadHashOrMojibake,
        rule: 'ALIAS_KEEPER_CANONICO' + suffixEnie, similarityPct: 98
      };
      resolutionCache.set(cacheKey, r2);
      return r2;
    }
  }

  const sKey = sortedTokenKey(restored);
  if (bySortedTokens.has(sKey)) {
    const r3 = {
      matched: true, chofer: bySortedTokens.get(sKey), restoredName: restored, hadHashOrMojibake,
      rule: 'PERMUTACION_INVERSA_TOKENS' + suffixEnie, similarityPct: 99
    };
    resolutionCache.set(cacheKey, r3);
    return r3;
  }

  const kTokens = getSignificantTokens(restored);
  const kSet = new Set(kTokens);
  if (kTokens.length >= 2) {
    const cands = byTokensList.filter(it =>
      (kTokens.every(t => it.tokenSet.has(t)) || it.tokens.every(t => kSet.has(t))) &&
      kSet.has(it.mainSurname)
    );
    if (cands.length === 1) {
      const r4 = {
        matched: true, chofer: cands[0].chofer, restoredName: restored, hadHashOrMojibake,
        rule: 'SUBCONJUNTO_TOKENS_CON_APELLIDO' + suffixEnie, similarityPct: 95
      };
      resolutionCache.set(cacheKey, r4);
      return r4;
    }
  }

  let bestCand = null, bestSim = 0;
  for (const item of byTokensList) {
    const surnameSim = Math.max(...kTokens.map(kt => tokenSimilarity(item.mainSurname, kt)));
    if (surnameSim < 0.72) continue;
    const shorter = kTokens.length <= item.tokens.length ? kTokens : item.tokens;
    const longer = kTokens.length <= item.tokens.length ? item.tokens : kTokens;
    if (shorter.length === 0) continue;
    let sumSim = 0;
    for (const st of shorter) {
      let maxS = 0;
      for (let i = 0; i < longer.length; i++) {
        const s = tokenSimilarity(st, longer[i]);
        if (s > maxS) maxS = s;
      }
      sumSim += maxS;
    }
    const score = sumSim / shorter.length;
    if (score > bestSim) { bestSim = score; bestCand = item.chofer; }
  }

  if (bestSim >= 0.85 && bestCand) {
    const r5 = {
      matched: true, chofer: bestCand, restoredName: restored, hadHashOrMojibake,
      rule: 'FUZZY_LEVENSHTEIN' + suffixEnie, similarityPct: Math.round(bestSim * 1000) / 10
    };
    resolutionCache.set(cacheKey, r5);
    return r5;
  }

  const rFail = {
    matched: false, chofer: null, restoredName: restored, hadHashOrMojibake,
    rule: 'CHOFER_EXTERNO_NO_EN_PARTICION_1',
    similarityPct: Math.round(bestSim * 1000) / 10,
    bestRejectedCandidate: bestCand ? bestCand.nombre : 'N/A'
  };
  resolutionCache.set(cacheKey, rFail);
  return rFail;
}

function parsePeriodoFlexible(rawVal, headerFallback) {
  const candidates = [rawVal, headerFallback].filter(Boolean);
  for (const val of candidates) {
    const s = String(val).trim().toLowerCase();
    if (!s) continue;
    const mDe = s.match(/(\d{1,2})\s+de\s+([a-z]+)\s+de\s+(\d{2,4})/);
    if (mDe) {
      const mesNum = MESES_MAP[mDe[2]];
      let anio = parseInt(mDe[3], 10);
      if (anio < 100) anio += 2000;
      if (mesNum && anio) return { anio, mesNumero: mesNum, mesPeriodo: `${anio}-${String(mesNum).padStart(2, '0')}`, mesTexto: `${MESES_NOMBRES[mesNum]} ${anio}` };
    }
    const mSlash = s.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{2,4})$/);
    if (mSlash) {
      const mesNum = parseInt(mSlash[2], 10);
      let anio = parseInt(mSlash[3], 10);
      if (anio < 100) anio += 2000;
      if (mesNum >= 1 && mesNum <= 12 && anio >= 2020) return { anio, mesNumero: mesNum, mesPeriodo: `${anio}-${String(mesNum).padStart(2, '0')}`, mesTexto: `${MESES_NOMBRES[mesNum]} ${anio}` };
    }
    const words = s.replace(/[^a-z0-9]+/g, ' ').trim().split(/\s+/);
    let foundMes = null, foundAnio = null;
    for (const w of words) {
      if (MESES_MAP[w]) foundMes = MESES_MAP[w];
      else if (/^\d{4}$/.test(w)) foundAnio = parseInt(w, 10);
    }
    if (foundMes && foundAnio) return { anio: foundAnio, mesNumero: foundMes, mesPeriodo: `${foundAnio}-${String(foundMes).padStart(2, '0')}`, mesTexto: `${MESES_NOMBRES[foundMes]} ${foundAnio}` };
  }
  return null;
}

function parseDecimal(val) {
  if (val === null || val === undefined || val === '') return 0;
  const n = parseFloat(String(val).replace(/\./g, '').replace(',', '.').trim());
  return isNaN(n) ? 0 : n;
}
function parseIntVal(val) {
  if (val === null || val === undefined || val === '') return 0;
  const n = parseInt(String(val).trim(), 10);
  return isNaN(n) ? 0 : n;
}
function parseTimeToHours(timeStr) {
  if (!timeStr) return 0;
  const parts = String(timeStr).trim().split(':');
  if (parts.length === 3) {
    return parseFloat(((parseFloat(parts[0]) || 0) + (parseFloat(parts[1]) || 0) / 60 + (parseFloat(parts[2]) || 0) / 3600).toFixed(2));
  }
  return 0;
}

function parseFechaIjl(rawVal) {
  if (!rawVal) return null;
  const s = String(rawVal).trim().toLowerCase();

  const mDateTime = s.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{2,4})[,\s]/);
  if (mDateTime) {
    const day = parseInt(mDateTime[1], 10);
    const mo = parseInt(mDateTime[2], 10);
    let yr = parseInt(mDateTime[3], 10);
    if (yr < 100) yr += 2000;
    return `${yr}-${String(mo).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
  }

  const m1 = s.match(/^(\d{1,2})[-\/]([a-z]{3,10})[-\/](\d{2,4})/);
  if (m1) {
    const day = parseInt(m1[1], 10);
    const mStr = m1[2];
    let yr = parseInt(m1[3], 10);
    if (yr < 100) yr += 2000;
    const mo = MESES_MAP[mStr];
    if (mo) {
      return `${yr}-${String(mo).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
    }
  }

  const m2 = s.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{2,4})$/);
  if (m2) {
    const day = parseInt(m2[1], 10);
    const mo = parseInt(m2[2], 10);
    let yr = parseInt(m2[3], 10);
    if (yr < 100) yr += 2000;
    return `${yr}-${String(mo).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
  }

  const m3 = s.match(/^(\d{4})[\/\-](\d{1,2})[\/\-](\d{1,2})/);
  if (m3) {
    return `${m3[1]}-${String(parseInt(m3[2], 10)).padStart(2, '0')}-${String(parseInt(m3[3], 10)).padStart(2, '0')}`;
  }

  const numVal = parseFloat(s.replace(',', '.'));
  if (!isNaN(numVal) && numVal > 30000 && numVal < 60000) {
    const utcDays = numVal - 25569;
    const ms = Math.round(utcDays * 86400 * 1000);
    const d = new Date(ms);
    if (!isNaN(d.getTime())) {
      const yr = d.getUTCFullYear();
      const mo = String(d.getUTCMonth() + 1).padStart(2, '0');
      const da = String(d.getUTCDate()).padStart(2, '0');
      return `${yr}-${mo}-${da}`;
    }
  }

  return null;
}

function parsePeriodoIjl(rawAnio, rawMes, rawFecha) {
  let anio = parseInt(String(rawAnio || '').trim(), 10);
  let mesNum = null;
  if (rawMes) {
    const sMes = String(rawMes).trim().toLowerCase();
    const mNum = sMes.match(/^(\d{1,2})/);
    if (mNum) {
      mesNum = parseInt(mNum[1], 10);
    }
  }
  if ((!anio || !mesNum) && rawFecha) {
    const pf = parseFechaIjl(rawFecha);
    if (pf) {
      const parts = pf.split('-');
      anio = parseInt(parts[0], 10);
      mesNum = parseInt(parts[1], 10);
    }
  }
  if (anio && mesNum && mesNum >= 1 && mesNum <= 12) {
    return {
      anio,
      mesNumero: mesNum,
      mesPeriodo: `${anio}-${String(mesNum).padStart(2, '0')}`,
      mesTexto: `${MESES_NOMBRES[mesNum]} ${anio}`
    };
  }
  return null;
}

const unifiedMap = new Map();
let normIcmCount = 0;
let noProcIcmCount = 0;
let normIspCount = 0;
let noProcIspCount = 0;
let normIjlCount = 0;
let noProcIjlCount = 0;
let ijlValidasCount = 0;
let ijlDescartadasCount = 0;
const itemsIjlParaUpsert = [];

// 1. Procesar RANKING ICM
for (let idx = 0; idx < icmItems.length; idx++) {
  const row = icmItems[idx];
  const rawMes = row.MES ?? row.col_1 ?? row['0'] ?? '';
  const rawChofer = row.CHOFER ?? row.col_2 ?? row['1'] ?? '';
  const rawTransp = String(row.TRANSPORTISTA ?? row.col_3 ?? row['2'] ?? '').trim();
  if (!rawMes && !rawChofer) continue;

  const p = parsePeriodoFlexible(rawMes, null);
  if (!p) continue;

  const res = resolveChoferParticion1(rawChofer);
  if (!res.matched) {
    noProcIcmCount++;
    continue;
  }

  if (res.rule !== 'EXACT_DIRECT' || res.hadHashOrMojibake) normIcmCount++;

  const tiempoStr = String(row.TIEMPO ?? row.col_4 ?? row['3'] ?? '0:00:00').trim();
  const tiempoHoras = parseTimeToHours(tiempoStr);
  const cantInf = parseIntVal(row['Cant. Infracciones'] ?? row.col_12 ?? row['11']);
  const icmVal = parseDecimal(row.ICM ?? row.col_9 ?? row['8']);

  const key = `${res.chofer.id}__${p.mesPeriodo}`;
  const prev = unifiedMap.get(key);
  if (prev && !(tiempoHoras > prev.tiempo_conduccion_horas || cantInf > prev.cant_infracciones)) continue;

  unifiedMap.set(key, {
    chofer_id: res.chofer.id, chofer_nombre: res.chofer.nombre, chofer_keeper_raw: res.restoredName,
    transportista: rawTransp, mes_texto: p.mesTexto, anio: p.anio, mes_numero: p.mesNumero, mes_periodo: p.mesPeriodo,
    tiempo_conduccion: tiempoStr, tiempo_conduccion_horas: tiempoHoras,
    infracciones_leves: parseIntVal(row.INFRACCIONES_LEVES ?? row.col_5 ?? row['4']),
    infracciones_medias: parseIntVal(row.INFRACCIONES_MEDIAS ?? row.col_6 ?? row['5']),
    infracciones_altas: parseIntVal(row.INFRACCIONES_ALTAS ?? row.col_7 ?? row['6']),
    cant_infracciones: cantInf, puntaje_icm: parseDecimal(row.PUNTAJE ?? row.col_8 ?? row['7']),
    icm: icmVal, icm_urbano: parseDecimal(row.ICM_URBANO ?? row.col_10 ?? row['9']),
    icm_no_urbano: parseDecimal(row.ICM_NO_URBANO ?? row.col_11 ?? row['10']),
    isp: prev ? prev.isp : null
  });
}

// 2. Procesar muestra de ISP desde nodo 3
for (let rIdx = 0; rIdx < ispItems.length; rIdx++) {
  const row = ispItems[rIdx];
  const rawMesCell = row['enero- 2026'] ?? '';
  const rawChoferCell = row['CHOFER'] ?? '';
  const rawIspCell = row['ISP'] ?? '';
  if (!rawChoferCell || String(rawChoferCell).trim().toUpperCase() === 'CHOFER') continue;
  const p = parsePeriodoFlexible(rawMesCell, 'enero 2026');
  if (!p) continue;
  const res = resolveChoferParticion1(rawChoferCell);
  if (!res.matched) { noProcIspCount++; continue; }
  if (res.rule !== 'EXACT_DIRECT' || res.hadHashOrMojibake) normIspCount++;
  const key = `${res.chofer.id}__${p.mesPeriodo}`;
  if (unifiedMap.has(key)) {
    const rec = unifiedMap.get(key);
    const ispVal = parseDecimal(rawIspCell);
    if (rec.isp === null || ispVal > rec.isp) rec.isp = ispVal;
  }
}

// 3. Procesar IJL RANKING desde nodo 3b (Agrupación Mensual por Chofer e Incidente)
const ijlAggMap = new Map();

for (let jIdx = 0; jIdx < ijlItems.length; jIdx++) {
  const row = ijlItems[jIdx];
  const rawAnio = row['AÑO'] ?? row.col_1 ?? row['0'] ?? '';
  const rawMes = row['MES'] ?? row.col_2 ?? row['1'] ?? '';
  const rawInc = String(row['INCIDENTE(Click to sort Ascending)'] ?? row.INCIDENTE ?? row.col_4 ?? row['3'] ?? '').trim();
  const rawFecha = row['FECHA(Click to sort Ascending)'] ?? row.FECHA ?? row.col_5 ?? row['4'] ?? '';
  const rawChofer = String(row['CHOFER'] ?? row.col_8 ?? row['7'] ?? '').trim();
  const rawEstado = String(row['ESTADO'] ?? row.col_9 ?? row['8'] ?? '').trim().toUpperCase();

  const p = parsePeriodoIjl(rawAnio, rawMes, rawFecha);
  if (!p || !rawInc) continue;

  if (rawEstado !== 'VALIDA') {
    ijlDescartadasCount++;
    continue;
  }
  ijlValidasCount++;

  const res = resolveChoferParticion1(rawChofer);
  if (!res.matched) {
    noProcIjlCount++;
    continue;
  }

  if (res.rule !== 'EXACT_DIRECT' || res.hadHashOrMojibake) normIjlCount++;

  const aggKey = `${res.chofer.id}__${p.mesPeriodo}__${rawInc}`;
  if (!ijlAggMap.has(aggKey)) {
    ijlAggMap.set(aggKey, {
      chofer_id: res.chofer.id,
      mes_periodo: p.mesPeriodo,
      incidente: rawInc,
      cantidad: 0
    });
  }
  ijlAggMap.get(aggKey).cantidad += 1;
}

// 4. Diffing O(1) contra Supabase (public.seguridad_vial puro ICM+ISP)
let omitidosCount = 0;
const itemsParaUpsert = [];

for (const [key, rec] of unifiedMap.entries()) {
  const pre = preMap.get(key);
  if (pre) {
    const sameHoras = Math.abs((pre.tiempo_conduccion_horas || 0) - rec.tiempo_conduccion_horas) < 0.01;
    const sameInf = pre.cant_infracciones === rec.cant_infracciones &&
                    pre.infracciones_leves === rec.infracciones_leves &&
                    pre.infracciones_medias === rec.infracciones_medias &&
                    pre.infracciones_altas === rec.infracciones_altas;
    const sameIcm = Math.abs((pre.icm || 0) - rec.icm) < 0.01 &&
                    Math.abs((pre.puntaje_icm || 0) - rec.puntaje_icm) < 0.01;
    const sameIsp = (pre.isp === null && rec.isp === null) ||
                    (pre.isp !== null && rec.isp !== null && Math.abs(pre.isp - rec.isp) < 0.01);

    if (sameHoras && sameInf && sameIcm && sameIsp) {
      omitidosCount++;
      continue;
    }
  }
  itemsParaUpsert.push(rec);
}

// 4b. Diffing O(1) para Incidentes Mensuales IJL contra public.seguridad_vial_incidentes_ijl
let omitidosIjlCount = 0;
const itemsIjlParaUpsert = [];

for (const [k, rec] of ijlAggMap.entries()) {
  const preQty = preIjlMap.get(k);
  if (preQty !== undefined && preQty === rec.cantidad) {
    omitidosIjlCount++;
    continue;
  }
  itemsIjlParaUpsert.push({
    chofer_id: rec.chofer_id,
    mes_periodo: rec.mes_periodo,
    incidente: rec.incidente,
    cantidad: rec.cantidad
  });
}

const statsObj = {
  total_unificados_sv: unifiedMap.size,
  modificados_sv: itemsParaUpsert.length,
  omitidos_sv: omitidosCount,
  total_incidentes_ijl_agrupados: ijlAggMap.size,
  incidentes_ijl_modificados: itemsIjlParaUpsert.length,
  incidentes_ijl_omitidos: omitidosIjlCount,
  ijl_validas: ijlValidasCount,
  ijl_descartadas: ijlDescartadasCount,
  normalizaciones_icm: normIcmCount,
  normalizaciones_isp: normIspCount,
  normalizaciones_ijl: normIjlCount,
  no_procesados_icm: noProcIcmCount,
  no_procesados_isp: noProcIspCount,
  no_procesados_ijl: noProcIjlCount
};

return [{
  json: {
    _no_changes: itemsParaUpsert.length === 0,
    batch_json_str: JSON.stringify(itemsParaUpsert).replace(/'/g, "''"),
    _no_changes_ijl: itemsIjlParaUpsert.length === 0,
    batch_ijl_json_str: JSON.stringify(itemsIjlParaUpsert).replace(/'/g, "''"),
    _stats: statsObj
  }
}];

function parseFechaISO(val) {
  if (!val) return null;
  const s = String(val).trim();
  if (!s || s === '-' || s.toUpperCase() === 'S/D' || s.toUpperCase() === 'OK') return null;
  const parts = s.split(/[\/\-]/);
  if (parts.length === 3) {
    let y = parseInt(parts[2], 10);
    if (y < 100) y += 2000;
    const m = String(parseInt(parts[1], 10)).padStart(2, '0');
    const d = String(parseInt(parts[0], 10)).padStart(2, '0');
    if (!isNaN(y) && !isNaN(parseInt(m, 10)) && !isNaN(parseInt(d, 10))) {
      return `${y}-${m}-${d}`;
    }
  }
  const isoMatch = s.match(/^\d{4}-\d{2}-\d{2}/);
  if (isoMatch) return isoMatch[0];
  return null;
}

function cleanTextDate(val) {
  if (!val) return null;
  const s = String(val).trim();
  if (!s || s === '-' || s.toUpperCase() === 'S/D' || s.toUpperCase() === 'OK') return null;
  return s;
}

function parseDateForScore(val) {
  if (!val) return null;
  const str = String(val).trim();
  const parts = str.split(/[\/\-]/);
  if (parts.length >= 3) {
    if (parts[0].length === 4) {
      const d = new Date(parseInt(parts[0], 10), parseInt(parts[1], 10) - 1, parseInt(parts[2], 10));
      return isNaN(d.getTime()) ? null : d;
    } else {
      const yr = parts[2].length === 2 ? 2000 + parseInt(parts[2], 10) : parseInt(parts[2], 10);
      const d = new Date(yr, parseInt(parts[1], 10) - 1, parseInt(parts[0], 10));
      return isNaN(d.getTime()) ? null : d;
    }
  }
  const d = new Date(str);
  return isNaN(d.getTime()) ? null : d;
}

function scoreRow(row) {
  let score = 0;
  let maxTime = 0;
  const fields = [row.mas, row.vtv, row.esp_es, row.vi, row.ve];
  for (const f of fields) {
    if (f) {
      score += 10;
      const d = parseDateForScore(f);
      if (d) {
        const t = d.getTime();
        if (t > maxTime) maxTime = t;
        if (d.getFullYear() >= 2026) score += 50;
      }
    }
  }
  return { score, maxTime };
}

function getVal(row, keys) {
  for (const k of keys) {
    if (row[k] !== undefined && row[k] !== null && String(row[k]).trim() !== '') {
      return String(row[k]).trim();
    }
  }
  return null;
}

// 1. Obtener datos preexistentes de Supabase
const pgData = $('1. Consultar Flota Preexistente (Supabase)').first()?.json || {};
const dbTractores = Array.isArray(pgData.tractores) ? pgData.tractores : [];
const dbSemis = Array.isArray(pgData.semis) ? pgData.semis : [];

const tracMap = new Map();
dbTractores.forEach(t => {
  if (t && t.patente) tracMap.set(String(t.patente).toUpperCase().replace(/\s+/g, ''), t);
});

const semisMap = new Map();
dbSemis.forEach(s => {
  if (s && s.patente) semisMap.set(String(s.patente).toUpperCase().replace(/\s+/g, ''), s);
});

// 2. Leer filas de Google Sheets
const rawItems = $input.all();
const rawRows = rawItems.map(item => item.json);

// 3. Deduplicar en memoria las patentes de la hoja
const dedupeMap = new Map();

for (let i = 0; i < rawRows.length; i++) {
  const r = rawRows[i];
  const pat = getVal(r, ['PATENTE', 'patente', 'Patente', 'DOMINIO', 'dominio', '0', 'col_1']);
  if (!pat) continue;
  const cleanPat = String(pat).toUpperCase().replace(/[^A-Z0-9]/g, '');
  if (!cleanPat || cleanPat === 'PATENTE' || cleanPat === 'DOMINIO' || cleanPat.length < 5 || cleanPat.length > 8) continue;

  const rowObj = {
    fila: i + 1,
    patente: cleanPat,
    mas: getVal(r, ['MAS', 'mas', 'Mas', 'M.A.S.', '1', 'col_2']),
    vtv: getVal(r, ['VTV', 'vtv', 'Vtv', 'V.T.V.', '2', 'col_3']),
    esp_es: getVal(r, ['ESP_ES', 'esp_es', 'ESP. ES.', 'ESP ES', 'Esp. Es.', 'ESPESOR', '3', 'col_4']),
    vi: getVal(r, ['VI', 'vi', 'Vi', 'V.I.', '4', 'col_5']),
    ve: getVal(r, ['VE', 've', 'Ve', 'V.E.', '5', 'col_6'])
  };

  const scoreObj = scoreRow(rowObj);
  rowObj._score = scoreObj.score;
  rowObj._maxTime = scoreObj.maxTime;

  if (!dedupeMap.has(cleanPat)) {
    dedupeMap.set(cleanPat, rowObj);
  } else {
    const existing = dedupeMap.get(cleanPat);
    if (rowObj._score > existing._score) {
      dedupeMap.set(cleanPat, rowObj);
    } else if (rowObj._score === existing._score && rowObj._maxTime >= existing._maxTime) {
      dedupeMap.set(cleanPat, rowObj);
    }
  }
}

// 4. Diffing O(1) delimitado estrictamente a Tractores (P2) y Semis (P3)
const deltaTractores = [];
const deltaSemis = [];
let omitidosCount = 0;
let fueraFlotaCount = 0;
let patentesFlotaDetectadas = 0;

for (const [pat, row] of dedupeMap.entries()) {
  const esTractor = tracMap.has(pat);
  const esSemi = semisMap.has(pat);

  if (!esTractor && !esSemi) {
    fueraFlotaCount++;
    continue;
  }

  patentesFlotaDetectadas++;

  // A. Evaluación para Tractores
  if (esTractor) {
    const existing = tracMap.get(pat);
    const vtvIso = parseFechaISO(row.vtv);
    const masIso = parseFechaISO(row.mas);

    const vtvDb = existing.vtv ? String(existing.vtv).substring(0, 10) : null;
    const masDb = existing.mas ? String(existing.mas).substring(0, 10) : null;

    const vtvChanged = (vtvIso || null) !== vtvDb;
    const masChanged = (masIso || null) !== masDb;

    if (vtvChanged || masChanged) {
      deltaTractores.push({
        id: existing.id,
        patente: pat,
        vtv: vtvIso,
        mas: masIso
      });
    } else {
      omitidosCount++;
    }
  }

  // B. Evaluación para Semis
  if (esSemi) {
    const existing = semisMap.get(pat);
    const vtvIso = parseFechaISO(row.vtv);
    const masIso = parseFechaISO(row.mas);
    const espVal = cleanTextDate(row.esp_es);
    const viVal = cleanTextDate(row.vi);
    const veVal = cleanTextDate(row.ve);

    const vtvDb = existing.vtv ? String(existing.vtv).substring(0, 10) : null;
    const masDb = existing.mas ? String(existing.mas).substring(0, 10) : null;
    const espDb = existing.esp_es ? String(existing.esp_es).trim() : null;
    const viDb = existing.vi ? String(existing.vi).trim() : null;
    const veDb = existing.ve ? String(existing.ve).trim() : null;

    const vtvChanged = (vtvIso || null) !== vtvDb;
    const masChanged = (masIso || null) !== masDb;
    const espChanged = (espVal || null) !== espDb;
    const viChanged = (viVal || null) !== viDb;
    const veChanged = (veVal || null) !== veDb;

    if (vtvChanged || masChanged || espChanged || viChanged || veChanged) {
      deltaSemis.push({
        id: existing.id,
        patente: pat,
        vtv: vtvIso,
        mas: masIso,
        esp_es: espVal,
        vi: viVal,
        ve: veVal
      });
    } else {
      omitidosCount++;
    }
  }
}

const totalDelta = deltaTractores.length + deltaSemis.length;

return [{
  json: {
    _no_changes: totalDelta === 0,
    has_tractores: deltaTractores.length > 0,
    has_semis: deltaSemis.length > 0,
    delta_tractores_count: deltaTractores.length,
    delta_semis_count: deltaSemis.length,
    batch_tractores_str: JSON.stringify(deltaTractores),
    batch_semis_str: JSON.stringify(deltaSemis),
    _stats: {
      total_filas_sheet: rawRows.length,
      patentes_unicas_en_sheet: dedupeMap.size,
      patentes_flota_detectadas: patentesFlotaDetectadas,
      tractores_modificados: deltaTractores.length,
      semis_modificados: deltaSemis.length,
      omitidos_identicos: omitidosCount,
      omitidos_fuera_flota: fueraFlotaCount
    }
  }
}];

const pData = $('3. Normalizar y Diffing O(1) Flota (Vencimientos)').first()?.json || {};
const st = pData._stats || {};
const totalEval = (st.tractores_modificados || 0) + (st.semis_modificados || 0) + (st.omitidos_identicos || 0);
const ahorroPct = totalEval > 0 ? (((st.omitidos_identicos || 0) / totalEval) * 100).toFixed(1) + '%' : '100%';

return [{
  json: {
    particion: 'Partición 13: Vencimientos Flota (Uni QM)',
    tablas_destino: ['public.tractores', 'public.semis'],
    sin_cambios_zero_egress: pData._no_changes === true,
    metricas_ejecucion: {
      filas_leidas_sheet: st.total_filas_sheet || 0,
      patentes_unicas_sheet: st.patentes_unicas_en_sheet || 0,
      patentes_flota_relevantes: st.patentes_flota_detectadas || 0,
      tractores_actualizados: st.tractores_modificados || 0,
      semis_actualizados: st.semis_modificados || 0,
      omitidos_identicos_sin_escritura: st.omitidos_identicos || 0,
      patentes_omitidas_fuera_flota: st.omitidos_fuera_flota || 0,
      ahorro_consultas_pct: ahorroPct
    },
    timestamp: new Date().toISOString()
  }
}];
